const userId = $json.jwtPayload?.userId;
if (!userId) return [{ json: { __error: true, __code: 401, __message: 'Token sin userId' } }];
// No se lee nada del query: el paciente es siempre el sujeto del token.
return [{ json: { user_id: String(userId) } }];

// Descarta el item vacío que emite Postgres sin filas (alwaysOutputData).
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const items = rows[0]?.items ?? [];
return [{ json: { __data: items, __meta: { total: items.length } } }];
